import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, TotalUsageMetadata} from '../index.js';
import type {ChatSession} from '../types/session.js';

it('exposes turn total usage to the response hook specs/hal-engine-config-hooks#9', async () => {
  const provider: AIProvider = {
    async *sendMessage() {
      yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 2, outputTokens: 3, totalTokens: 5}};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  let total: TotalUsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
    hooks: {afterModelResponse: async (_session, _text, usage) => { total = usage; }},
  });
  const session: ChatSession = {sessionId: '1', userId: '1', entries: []};
  await orchestrator.processMessage(session);
  expect(total).toEqual({inputTokens: 2, outputTokens: 3, totalTokens: 5});
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/totalUsageContract.test.ts"
